Let $\mathbf{R}$ be a non-empty set of variables and $\mathbb{Z}$ be a collection of sets of variables in $\mathcal{G}$. A thicket $\mathcal{J}$ is a subgraph of $\mathcal{G}$ which is an $\mathbf{R}$-rooted c-component consisting of a minimal c-component over $\mathbf{R}$ and hedges
            \begin{equation*}
                \mathbb{F}_{\mathcal{J}} := \{\langle \mathcal{F}_{\mathbf{Z}}, \mathcal{J}[\mathbf{R}]\rangle \mid \mathcal{F}_{\mathbf{Z}} \subseteq \mathcal{G}[\mathbf{V}\setminus\mathbf{Z}], \mathbf{Z}\cap \mathbf{R}=\varnothing\}_{\mathbf{Z}\in \mathbb{Z}}.
            \end{equation*}

\textbf{In Figure \ref{fig:countr_exmpl_complex}:} This graph is a thicket, also displayed in Figure \ref{subfig: thicket exmple 2 }.  Let $\mathbb{F_{\mathcal{J}}}$ be
        \begin{equation*}
            \mathbb{F_{\mathcal{J}}} = \{\langle \mathcal{F}, \mathcal{F}'\rangle \},
        \end{equation*}
        where $\mathcal{F} = \mathcal{G}[\{R, T_1, T_2, T_3\}]$ and $\mathcal{F}' = \mathcal{G}[\{R\}]$.
        One can observe that thicket $\mathcal{J}$ is formed for the causal effect $\mathbf{X} = \{T_1, T_2, T_3\}$ on $\mathbf{Y} = \{R\}$.

Herein, we study Figure \ref{fig:countr_exmpl_complex} in more details and show that the models in \citep{lee2019general} violate the relaxed positivity assumption. 
        To this end, we present the models $\mathcal{M}_1$ and $\mathcal{M}_2$ constructed in \citep{lee2019general} for the thicket $\mathcal{J}$ which is defined for this case in Appendix \ref{apn: A notation}. 
        By the construction, each variable from $\{U_1, U_2, U_3, T_3\}$ is a binary number, i.e., $\{0, 1\}$ and each variable from $\{T_1, T_2\}$ is a vector of length two, because each variable from $\{U_1, U_2, U_3, T_3\}$ appears in only one hedgelet and each variables in $\{T_1, T_2\}$ appears in exactly two different hedgelets. 
        Thus, $T_1=(T_{1, 1}, T_{1, 2})$ and $T_2 = (T_{2, 1}, T_{2, 2})$, where $T_{1, 1}, T_{1, 2}, T_{2, 1}, T_{2, 2}$ are binary numbers. The first coordinate captures some properties of the hedgelet $\mathcal{H}_1$ while the second coordinate captures some properties of the hedgelet $\mathcal{H}_2$. 
        \cite{lee2019general} define both models $\mathcal{M}_1, \mathcal{M}_2$ for the hedgelet $\mathcal{H}_1$ as
        \begin{align*}
            & T_3 = U_2 \oplus U_3, \quad T_{2, 1} = T_3, \quad T_{1, 1} = T_{2, 1} \oplus U_2,
        \end{align*}
        and for the hedgelet $\mathcal{H}_2$ as
        \begin{align*}
            & T_{2, 2} = U_1, \quad T_{1, 2} = T_{2, 2}, \quad T_{2, 2} = U_1.
        \end{align*}
        Additionally, in model $\mathcal{M}_1$, variable $R$ is defined by
        \begin{equation*}
            R = \mathds{1}_{T_{1, 1} = 0} \wedge \mathds{1}_{T_{1, 2}=0} \wedge \mathds{1}_{U_3=1} \wedge \mathds{1}_{U_{1} = 1},
        \end{equation*}
        and in model $\mathcal{M}_2$, it is defined to be zero, i.e., $R = 0$.

Let $\mathbf{W} \subseteq \mathbf{C} \subseteq \mathbf{V}$, $\mathbf{T} = \mathbf{C} \setminus \mathbf{W}$, $\mathbf{S}=\mathbf{V} \setminus \mathbf{T}$. 
            If $\mathbf{W}$ is an ancestral set in $\mathcal{G}[\mathbf{C}]$, then:
            \begin{equation*}
                Q[\mathbf{W}] = \sum_{\mathbf{C} \setminus \mathbf{W}}Q[\mathbf{C}].
            \end{equation*}

Consider a set of vectors $\{c_i\}_{i=1}^{n}$, where $c_i \in \mathbb{R}^d$. Assume $c\in \mathbb{R}^d$ is a vector that is linearly independent of $\{c_i\}_{i=1}^{n}$, then there is a vector $b\in \mathbb{R}^d$ such that
            \begin{align*}
                & \langle c_i, b \rangle = 0, \quad \forall i \in [1:n],\\
                & \langle c, b \rangle \neq 0.
            \end{align*}

Denote by $\{\phi_i\}_{i=1}^{l}$ a subset of $\{c_i\}_{i=1}^{n}$ which forms a basis for the vectors in $\{c_i\}_{i=1}^{n}$. Clearly, we have $l < d$. Now, consider the following system of linear equations with respect to $b$:
            \begin{equation} \begin{split}
                & \langle \phi_i, b \rangle = 0, \quad \forall i\in[1:l], \\
                & \langle c, b \rangle = 13\neq0.
            \end{split}
            \end{equation}
            By the assumption, vectors in $\{\phi_i\}_{i=1}^{l}\cup\{c\}$ are linearly independent, thus there exists a solution to \eqref{eq: lem11}.

\begin{split}
                & \langle \phi_i, b \rangle = 0, \quad \forall i\in[1:l], \\
                & \langle c, b \rangle = 13\neq0.
            \end{split}

Let $\mathbf{W}:=\Anc{\mathbf{Y}}{\mathcal{G}_{\mathbf{V} \setminus \mathbf{X}}}$.
            Since $Q[\mathbf{V} \setminus \mathbf{X}] = P_{\mathbf{x}}(\mathbf{V} \setminus \mathbf{X})$, using marginalization, we obtain
            \begin{equation} P_{\mathbf{x}}(\mathbf{y}) = \sum_{\mathbf{V} \setminus (\mathbf{X} \cup \mathbf{Y})}Q[\mathbf{V} \setminus \mathbf{X}] = \sum_{\mathbf{W} \setminus \mathbf{Y}} \sum_{\mathbf{V} \setminus (\mathbf{W} \cup \mathbf{X})} Q[\mathbf{V} \setminus \mathbf{X}].
            \end{equation}
            Since $\mathbf{W}$ is an ancestral set in $\mathcal{G}[\mathbf{V} \setminus \mathbf{X}]$, Lemma \ref{lemma: Q-marginal} implies
            \begin{equation*}
                \sum_{\mathbf{V} \setminus (\mathbf{W} \cup \mathbf{X})} Q[\mathbf{V} \setminus \mathbf{X}] = Q[\mathbf{W}].
            \end{equation*}
            Substituting the above equation into \eqref{eq:app_prp3} implies
            \begin{equation} P_{\mathbf{x}}(\mathbf{y}) = \sum_{\mathbf{W} \setminus \mathbf{Y}} Q[\mathbf{W}] = P_{\mathbf{v}\setminus \mathbf{w}}(\mathbf{y}).
            \end{equation}
            \textit{Sufficient part:} 
            Suppose $Q[\mathbf{W}]$ is g-identifiable from $(\mathbb{A},\mathcal{G})$.
            Equation \eqref{eq: prp 3 proof} implies that $P_{\mathbf{x}}(\mathbf{y})$ is uniquely computable from $Q[\mathbf{W}]$, and therefore, the causal effect of $\mathbf{X}$ on $\mathbf{Y}$ is g-identifiable from $(\mathbb{A},\mathcal{G})$.

            \textit{Necessary part:}
            Suppose $Q[\mathbf{W}]$ is not g-identifiable from $(\mathbb{A}, \mathcal{G})$. 
            For each $W \in \mathbf{W} \setminus \mathbf{Y}$, there exists a directed path in $\mathcal{G}[\mathbf{W}]$ from $W$ to a variable in $\mathbf{Y}$. 
            Hence, Lemma \ref{lemma: prp3 - 3} implies that the causal effect of $\mathbf{V} \setminus \mathbf{W}$ on $\mathbf{Y}$ is not g-identifiable from $(\mathbb{A}, \mathcal{G})$. 
            Hence, Equation \eqref{eq: prp 3 proof} implies that $ P_{\mathbf{x}}(\mathbf{y})$ cannot be uniquely computed and the causal effect of $\mathbf{X}$ on $\mathbf{Y}$ is not g-identifiable from $(\mathbb{A},\mathcal{G})$.

If $Q[\mathbf{S}]$ is not g-identifiable from $(\mathbb{A}', \mathcal{G}')$, then there exists two models $\mathcal{M}_1'$ and $\mathcal{M}_2'$ in $\mathbb{M}^+(\mathcal{G}')$ such that for each $i\in [0:m]$ and any $\mathbf{v} \in \dom{\mathbf{V}'}$,
        \begin{equation*}
            Q^{\mathcal{M}_1'}[\mathbf{A}_i'](\mathbf{v}) = Q^{\mathcal{M}_2'}[\mathbf{A}_i'](\mathbf{v}), 
        \end{equation*}
        and there exists $\mathbf{v}_0 \in \dom{\mathbf{V}'}$ such that 
        \begin{equation*}
            Q^{\mathcal{M}_1'}[\mathbf{S}](\mathbf{v}_0) \neq Q^{\mathcal{M}_2'}[\mathbf{S}](\mathbf{v}_0).
        \end{equation*}

        Next, we will construct two models $\mathcal{M}_1$ and $\mathcal{M}_2$ in $\mathbb{M}^+(\mathcal{G})$ to prove that $Q[\mathbf{S}]$ is not g-identifiable from $(\mathbb{A}, \mathcal{G})$. 
        We define the domains of variables in $\mathbf{V}'$ in the model $\mathcal{M}_i$ similar to model $\mathcal{M}_i'$, for $i \in \{1, 2\}$. 
        Since for each node $V\in\mathbf{V}'$, we have $\Pa{V}{\mathcal{G}'}\subseteq\Pa{V}{\mathcal{G}}$, then for all $V\in \mathbf{V}'$ and $i \in \{1, 2\}$, we can define:
        \begin{equation*}
            P^{M_i}(V|\Pa{V}{\mathcal{G}}) := P^{M_i'}(V \mid \Pa{V}{\mathcal{G}'}).
        \end{equation*}
        And for $V \in \mathbf{V} \setminus \mathbf{V}'$, we define:
        \begin{equation*}
            \dom{V} = \{0\}, \quad P(V=0)=1.
        \end{equation*}
        Because variable $V \in \mathbf{V} \setminus \mathbf{V}'$ can only take value $0$ with probability one, then $Q^{\mathcal{M}_j}[\mathbf{A}_i](\mathbf{v})=Q^{\mathcal{M}'_j}[\mathbf{A}'_i](\mathbf{v})$ for all $i$ and $Q^{\mathcal{M}_j}[\mathbf{S}](\mathbf{v}_0)=Q^{\mathcal{M}_j'}[\mathbf{S}](\mathbf{v}_0)$ for $j\in\{1,2\}$. 
        Thus, we have
        \begin{align*}
            &Q^{\mathcal{M}_1}[\mathbf{A}_i](\mathbf{v}) = Q^{\mathcal{M}_2}[\mathbf{A}_i](\mathbf{v}), \quad i\in[0:m],\\
            &Q^{\mathcal{M}_1}[\mathbf{S}](\mathbf{v}_0) \neq Q^{\mathcal{M}_2}[\mathbf{S}](\mathbf{v}_0).
        \end{align*}
        This shows that $Q[\mathbf{S}]$ is not g-identifiable from $(\mathbb{A}, \mathcal{G})$.

Lets fix a realization $\mathbf{v}$ for the observed variables $\mathbf{V}'$.
        Suppose that $l_1$ and $l_2$ are two integers such that
        \begin{equation*}
        \begin{split}
            & \gamma_{l_1} = (2x, 0, \dots, 0)),\\
            & \gamma_{l_2} = (2x+2 \pmod{\kappa+1}, 0, \dots, 0),
        \end{split}
        \end{equation*}
        where $x$ is any fixed integer in $[0 : \frac{\kappa-1}{2}]$.
        To show the result, we will prove that $\theta_{i, l_1}(\mathbf{v})=\theta_{i, l_2}(\mathbf{v})$. Let
        \begin{align*}
            &f_{i, j}(\mathbf{v}, \mathbf{u}^{\mathbf{T}}) := \sum_{\mathbf{u}\in\mathbf{U}^{\mathbf{S}}} \prod_{V \in \mathbf{A}'_i} P(v \mid \Pa{V}{\mathcal{G}'})\! \prod_{U\in \mathbf{U}' \setminus \{U_0\}}\! P(u)\\
            & = \prod_{V \in \mathbf{A}'_i\setminus\mathbf{B}_i} P(v \mid \Pa{V}{\mathcal{G}'})\! \prod_{V \in \mathbf{B}_i\setminus\mathbf{S}} P(v \mid \Pa{V}{\mathcal{G}'})\!\sum_{\mathbf{u}\in\mathbf{U}^{\mathbf{S}}}\prod_{V \in \mathbf{S}} P(v \mid \Pa{V}{\mathcal{G}'}) \prod_{U\in \mathbf{U}' \setminus \{U_0\}}\! P(u). 
        \end{align*}
        where index $j$ indicates $U_0=\gamma_j$. Note that variable $U_0$ may appear in the parent set of some observed variables. 
        Using the above definition, we have
        \begin{equation*}
            \theta_{i, j}(\mathbf{v}) = \sum_{\mathbf{u}^\textbf{T}\in\mathbf{U}^{\mathbf{T}}} f_{i, j}(\mathbf{v}, \mathbf{u}^{\mathbf{T}}).
        \end{equation*}
        Hence, if we show $f_{i, l_1}(\mathbf{v}, \mathbf{u}^{\mathbf{T}})=f_{i, l_2}(\mathbf{v}, \mathbf{u}^{\mathbf{T}})$ for any fixed realization $\mathbf{u}^{\mathbf{T}}$, the above equation implies $\theta_{i, l_1}(\mathbf{v})=\theta_{i, l_2}(\mathbf{v})$. 

        When $T\in \mathbf{A}'_i\setminus\mathbf{B}_i$, then for fixed realizations of $\textbf{u}^{\mathbf{T}}$,  $P(t|\Pa{T}{\mathcal{G}'})$ is the same for both realizations $\gamma_{l_1}$ and $\gamma_{l_2}$ since $\gamma_{l_1}\equiv\gamma_{l_2}$ mod 2.

        When $T\in \mathbf{B}_i\setminus\mathbf{S}$, unobserved variables in $\Pa{T}{\mathcal{G}'}$ are a subset of $\mathbf{U}^{\mathbf{T}}\cup\{U_0\}$. Note that in the definition of $f_{i, j}(\mathbf{v}, \mathbf{u}^{\mathbf{T}})$, all such unobserved variables are fixed. 
        Thus, if there exists $T\in \mathbf{B}_i\setminus\mathbf{S}$, such that $P(t|\Pa{T}{\mathcal{G}'})=0$, then 
        \begin{equation*}
        f_{i, l_1}(\mathbf{v}, \mathbf{u}^{\mathbf{T}})=f_{i, l_2}(\mathbf{v}, \mathbf{u}^{\mathbf{T}})=0.
        \end{equation*}
        When $P(t|\Pa{T}{\mathcal{G}'})=1$ for all $T\in \mathbf{B}_i\setminus\mathbf{S}$,
        to prove $f_{i, l_1}(\mathbf{v}, \mathbf{u}^{\mathbf{T}})=f_{i, l_2}(\mathbf{v}, \mathbf{u}^{\mathbf{S}})$, we show that for any realization $(\textbf{u}_1,\gamma_{l_1})$ of $(\mathbf{U}^{\mathbf{S}},U_0)$, there is a realization $(\textbf{u}_2,\gamma_{l_2})$  of $(\mathbf{U}^{\mathbf{S}},U_0)$ such that 
        \begin{equation*}
            \prod_{V \in \mathbf{S}} P(v \mid \Pa{V}{\mathcal{G}'})\Big|_{(\mathbf{U}^{\mathbf{S}},U_0)=(\textbf{u}_1,\gamma_{l_1})}=\prod_{V \in \mathbf{S}} P(v \mid \Pa{V}{\mathcal{G}'})\Big|_{(\mathbf{U}^{\mathbf{S}},U_0)=(\textbf{u}_2,\gamma_{l_2})},
        \end{equation*}
        where $P(v \mid \Pa{V}{\mathcal{G}'})\Big|_{(\mathbf{U}^{\mathbf{S}},U_0)=(\textbf{u}_1,\gamma_{l_1})}$ denotes the conditional probability of $v$ given its parents in which the unobserved variables $(\mathbf{U}^{\mathbf{S}},U_0)$ are fixed to be  $(\textbf{u}_1,\gamma_{l_1})$.
        To this end, we consider two cases depending on $i$. 

        \textbf{First case, when $i \in [0:k]$:} 
        In this case, we have
        \begin{equation} t[i] = \left( \sum_{Y \in \Pa{T}{\mathcal{F}_i}} y[i] \right) \pmod{2}.
        \end{equation}

        Consider the set $\mathbf{\Lambda}:=\Pa{\mathbf{S}}{\mathcal{F}_i}\setminus \Pa{\mathbf{S}}{\mathcal{F}_i[\mathbf{S}]}$, that is the set of all parents of nodes in $\textbf{S}$ that are outside of $\textbf{S}$. By the construction of our models, summation of the values of the observed and unobserved nodes in $\mathbf{\Lambda}$ are the same, i.e.,  
        \begin{equation*}
            \sum_{W \in \mathbf{\Lambda}\cap \mathbf{B}_i} w[i] \equiv \sum_{W \in \mathbf{\Lambda}\cap \mathbf{U}'} w[i] \pmod{2},
        \end{equation*}
        or equivalently
        \begin{equation} \sum_{W \in \mathbf{\Lambda}} w[i] \equiv 0 \pmod{2}.
        \end{equation}
        This is because, in graph $\mathcal{F}_i$, each observed variable outside of $\mathbf{S}$ has at most one child outside of $\mathbf{S}$, and each unobserved node has either one or two children outside of $\mathbf{S}$. 
        According to (\ref{eq: tmp1}), those unobserved nodes with two children outside of $\mathbf{S}$ do not belong to $\mathbf{\Lambda}\cap \mathbf{U}'$. 
        Such unobserved nodes have exactly two observed descendants in $\mathbf{\Lambda}\cap \mathbf{B}_i$, and because both descendants appear in \eqref{eq: tmp2}, their summation is zero mod 2. 
        On the other hand, the unobserved nodes with only one child outside of $\mathbf{S}$ belong to $\mathbf{\Lambda}\cap \mathbf{U}'$ and have exactly one observed descendant in $\mathbf{\Lambda}\cap \mathbf{B}_i$. Thus, the summation of such unobserved variables and their observed descendant is again zero mod 2 in \eqref{eq: tmp2}.

        If $\mathbb{I}(S)=0$ for all $S \in \mathbf{S}$, then by our model construction, for any variable $W \in \mathbf{\Lambda}\setminus \{T_i\}$, $w[i]$ is an even number but $T_i$ takes value 1 with probability one. 
        Hence, the summation in \eqref{eq: tmp2} cannot be an even number.
        Therefore, there exists at least a variable $S\in \mathbf{S}$ such that $\mathbb{I}(S)=1$. 
        In this case, the value of $P(S|\Pa{S}{\mathcal{G}'})$ does not depend on the realizations of variables in $\mathbf{U}^{\mathbf{S}}$. 
        Next, we show that for any realization $\mathbf{u}_{1}$ of $\mathbf{U}^{\mathbf{S}}$, there is a realization $\mathbf{u}_{2}$ such that 
        \begin{equation} P(s|\Pa{S}{\mathcal{G}'})\Big|_{(\mathbf{U}^{\mathbf{S}},U_0)=(\textbf{u}_1,\gamma_{l_1})}=P(s|\Pa{S}{\mathcal{G}'})\Big|_{(\mathbf{U}^{\mathbf{S}},U_0)=(\textbf{u}_2,\gamma_{l_2})}.
        \end{equation}
        Since $\mathcal{G}'_{\mathbf{S}}$ is a c-component, there exists a sequence of variables $U_0, \hat{S}_1, \hat{U}_1, \hat{S}_2, \hat{U}_2, \dots, \hat{U}_l, S$, such that $U_0$ is a parent of $\hat{S}_1$, $S$ is a children of $\hat{U}_l$ and $\hat{U}_j$ is a parent of variables $\hat{S}_j$ and $\hat{S}_{j+1}$ for $j \in [1:l-1]$. 
        Let $\hat{\mathbf{U}}:=\{\hat{U}_1, \dots, \hat{U}_l\}$. 
