In this section, we provide our proof for the necessary part of Theorem \ref{thm: main} when $\mathbf{S}\nsubseteq \mathbf{A}_i'$ for all $i\in [0:m]$. 

    We define $\mathcal{F}^{\mathbf{S}}$ to be a minimal (in terms of edges) spanning subgraph of $\mathcal{G}[\mathbf{S}]$ such that $\mathcal{F}^{\mathbf{S}}_{\mathbf{S}}$ is a single c-component. 
    In this case, we can assume $\mathbf{V}' = \mathbf{S}$, $\mathcal{G}'$ is $\mathcal{F}^{\mathbf{S}}$, and $\mathbb{A}'= \{\mathbf{A}_i':=\mathbf{A}_i \cap \mathbf{V}'\}_{i=0}^m$. 
    For each $i\in [0:m]$, we have $\mathbf{A}_i' \subsetneq \mathbf{V}'$. 
    Note that Lemma \ref{lem: simplify} holds for this case. 
    Hence, it is enough to show that $Q[\mathbf{S}]$ is not g-identifiable from $(\mathbb{A}', \mathcal{G}')$. 

    Recall that our assumptions and goal in this section are as follows:\\
    $\mathcal{G}'$ is a DAG with observed variables $\mathbf{V}'$ and unobserved variables $\mathbf{U}'$ such that $\mathcal{G}'_{\mathbf{V}'}$ has no directed edges and its bidirected edges form a spanning tree over $\mathbf{V}'$. 
    $\mathbb{A}'= \{\mathbf{A}_i'\}_{i=0}^m$ is a collection of subsets such that $\mathbf{A}_i' \subsetneq \mathbf{V}'$. 
    The goal is to show that $Q[\mathbf{V}']$ is not g-identifiable from $(\mathbb{A}',\mathcal{G}')$.

    For this case we will define two model $\mathcal{M}_1$ and $\mathcal{M}_2$ such that for each $i\in [0:m]$ and any $\mathbf{v}\in \dom{\mathbf{V}'}$,
    \begin{equation*}
        Q^{\mathcal{M}_1}[\mathbf{A}_i'](\mathbf{v}) = Q^{\mathcal{M}_2}[\mathbf{A}_i'](\mathbf{v}),
    \end{equation*}
    but there exists $\mathbf{v}_0\in \dom{\mathbf{V}'}$ such that
    \begin{equation*}
        Q^{\mathcal{M}_1}[\mathbf{S}](\mathbf{v}_0) \neq Q^{\mathcal{M}_2}[\mathbf{S}](\mathbf{v}_0).
    \end{equation*}

    For both models $\mathcal{M}_1$ and $\mathcal{M}_2$ we define each observed and unobserved variable to be binary, i.e $\dom{W}=\{0, 1\}$ for all $W \in \mathbf{V}' \cup \mathbf{U}'$.
    Next, we define the equation of the variables in each model. 

    \textbf{Model 1}: For $V \in \mathbf{V}'$:
    \begin{align}
        V = 
        \begin{cases}
            \bigoplus \Pa{V}{\mathcal{G}'}, \quad \text{with probability } 1-\epsilon,\\
            1, \quad \text{with probability } \frac{\epsilon}{2},\\
            0, \quad \text{with probability } \frac{\epsilon}{2},
        \end{cases}
    \end{align}
    and for $U \in \mathbf{U}'$:
    \begin{equation*}
        P(U=0)= P(U=1) = 0.5.
    \end{equation*}

    \textbf{Model 2}: Suppose $V_1$ is a fixed observed variable in $\mathbf{V}'$. 
    Then, for all $V$ in $\mathbf{V}'\setminus \{V_1\}$ we define:
    \begin{align}
        V = 
        \begin{cases}
            \bigoplus \Pa{V}{\mathcal{G}'}, \quad \text{with probability } 1-\epsilon \\
            1, \quad \text{with probability } \frac{\epsilon}{2},\\
            0, \quad \text{with probability } \frac{\epsilon}{2},
        \end{cases}
    \end{align}
    and for $V_1$:
    \begin{align}
        V_1 = 
        \begin{cases}
            \urcorner\bigoplus \Pa{V_1}{\mathcal{G}'}, \quad \text{with probability } 1-\epsilon \\
            1, \quad \text{with probability } \frac{\epsilon}{2},\\
            0, \quad \text{with probability } \frac{\epsilon}{2},
        \end{cases}
    \end{align}
    where $\urcorner$ denotes the logical not. 
    Similar to the first mode, for each unobserved variables $U\in\mathbf{U}'$, 
    \begin{equation*}
        P(U=0)= P(U=1) = 0.5.
    \end{equation*}

    \begin{lemma}
        Let $i \in [0, m]$ and denote the cardinality of $\mathbf{A}_i'$ by $n$, i.e. $|\mathbf{A}_i'|=n$. 
        Then for any realization $\mathbf{v}\in \dom{\mathbf{V}'}$:
        $$
        Q^{\mathcal{M}_1}[\mathbf{A}_i'](\mathbf{v}) = Q^{\mathcal{M}_2}[\mathbf{A}_i'](\mathbf{v}) = \frac{1}{2^n}.
        $$
    \end{lemma}
    \begin{proof}
        Suppose $\mathbf{A}_i':= \{A_1, A_2, \dots, A_n\}$. Since $\mathbf{A}_i' \subsetneq \mathbf{V}'$, there are distinct unobserved variables $U_1, U_2, \dots, U_n$, such that $U_j$ is a parent of the $A_j$ for $j \in [1: n]$. Denote by $\mathcal{M}$ any of the model $\mathcal{M}_1$ or $\mathcal{M}_2$. 

        Assume that for some realization of observed and unobserved variables, exactly $t\in [0, n]$ variables in $\mathbf{A}'_i$ are defined by the $XOR$ or $\urcorner XOR$ of their parents. Without loss of generality, assume that these variables are $\{A_1, A_2, \dots, A_t\}$. If we know all unobserved variables $\mathbf{U}'$ except $\{U_1, U_2, \dots, U_t\}$, then we can determine uniquely the values of $\{U_1, U_2, \dots, U_t\}$ from the following equations:
        \begin{equation*}
            A_i = \bigotimes \Pa{A_i}{\mathcal{G}'},\quad i\in [1:t],
        \end{equation*}
        where $\bigotimes$ denotes the corresponding equation, either $XOR$ or $\urcorner XOR$, for variable $A_i$ in model $\mathcal{M}$. 
        Thus, by considering all possible realizations of unobserved variables that lead to a realization $\mathbf{v} \in \dom{\mathbf{V}'}$, we obtain
        \begin{equation*}
            Q[\textbf{A}_i'] = \sum_{j=0}^n C_n^j(1-\epsilon)^j\left( \frac{\epsilon}{2} \right)^{n-j} \left(\frac{1}{2}\right)^j = \left(\frac{1}{2}\right)^n,
        \end{equation*}
        where $C_n^j$ is the number of different ways to choose $j$ variables out of $n$, such that with probability $(1-\epsilon)$ their values are determined by either $XOR$ or $\urcorner XOR$ equation. All other $n-j$ variables are equal to either $0$ or $1$ with probability $\frac{\epsilon}{2}$.
    \end{proof} 

    \begin{lemma}
        Let $\mathbf{v}=\mathbf{0}$ be the realization of $\mathbf{V}'$ such that all observed variables are equal to $0$. 
        Then $Q^{\mathcal{M}_1}[\mathbf{V}'](\mathbf{v}) \neq Q^{\mathcal{M}_2}[\mathbf{V}'](\mathbf{v})$.
    \end{lemma}
    \begin{proof}
        Define  $n=|\mathbf{V}'|$ and $\mathbf{V}' = \{V_1, V_2, \dots, V_n\}$. Firstly, we will prove that for any $\mathbf{v} \in \dom{\mathbf{V}'}$, the value of $Q^{\mathcal{M}_2}[\mathbf{V}'](\mathbf{v})$ does not depend on the position of $V_1$ in graph $\mathcal{G}'$. 
        Denote by $V_2$ an observed variable which is connected to the $V_1$ by a bidirected edge in $\mathcal{G}'_{\mathbf{V}'}$.
        Let $U$ denotes the unobserved variable (corresponding to the bidirected edge) which is a parent of $V_1$ and $V_2$. 
        Next, we define a new model $\mathcal{M}_2'$ in which all variables in $\mathbf{V}'$ are defined similarly as they are defined in model $\mathcal{M}_2$ except for variables $V_1$ and $V_2$. 
        In $\mathcal{M}_2'$, we define $V_2$ in the same way as $V_1$ is defined in  $\mathcal{M}_2$.
        We also define $V_1$ in $\mathcal{M}_2'$ in the same way as $V_2$ is defined in $\mathcal{M}_2$.
        Then, we have
        \begin{align*}
            \prod_{i=1}^n P^{\mathcal{M}_2}(v_i|\Pa{V_i}{\mathcal{G}'}) = P^{\mathcal{M}_2}(v_1|\Pa{V_1}{\mathcal{G}'})P^{\mathcal{M}_2}(v_2|\Pa{V_2}{\mathcal{G}'})\prod_{i=3}^{n}P(v_i|\Pa{V_i}{\mathcal{G}'}) \\
            = P^{\mathcal{M}_2'}(v_1|\Pa{V_1}{\mathcal{G}'}\setminus\{U\}, u\oplus 1)P^{\mathcal{M}_2'}(v_2|\Pa{V_2}{\mathcal{G}'}\setminus\{U\}, u\oplus 1)\prod_{i=3}^{n}P(v_i|\Pa{V_i}{\mathcal{G}'}).
        \end{align*}
        This implies that substituting $V_1$ by $V_2$ does not change the value of $Q^{\mathcal{M}_2}[\mathbf{V}'](\mathbf{v})$.

        Without loss of generality, suppose that $V_1$ is a leaf in $\mathcal{G}'$ and $U_1$ is a parent of $V_1$. Note that there are exactly $n-1$ unobserved variables in graph $\mathcal{G}'$.
        This is because $\mathcal{G}'_{\mathbf{V}'}$ is a tree with bidirected edges over $\mathbf{V}'$. Therefore, we have
        \begin{align*}
            & 2^{n-1}Q^{\mathcal{M}_1}[\mathbf{V}'](\mathbf{0}) = P^{\mathcal{M}_1}(V_1=0|U_1=0)\!\! \sum_{\mathbf{U}' \setminus \{ U_1\}} \prod_{j>1}P(v_j|\Pa{V_j}{\mathcal{G}'}) + P^{\mathcal{M}_1}(V_1=0|U_1=1)\!\! \sum_{\mathbf{U}' \setminus \{ U_1\}} \prod_{j>1}P(v_j|\Pa{V_j}{\mathcal{G}'}), \\
            & 2^{n-1}Q^{\mathcal{M}_2}[\mathbf{V}'](\mathbf{0}) = P^{\mathcal{M}_2}(V_1=0|U_1=0)\!\! \sum_{\mathbf{U}' \setminus \{ U_1\}} \prod_{j>1}P(v_j|\Pa{V_j}{\mathcal{G}'}) + P^{\mathcal{M}_2}(V_1=0|U_1=1)\!\! \sum_{\mathbf{U}' \setminus \{ U_1\}} \prod_{j>1}P(v_j|\Pa{V_j}{\mathcal{G}'}).
        \end{align*}
        Note that:
        \begin{align*}
            & P^{\mathcal{M}_1}(V_1=0|U_1=0) = 1 -\frac{\epsilon}{2}\\
            & P^{\mathcal{M}_1}(V_1=0|U_1=1) = \frac{\epsilon}{2}\\
            & P^{\mathcal{M}_2}(V_1=0|U_1=0) = \frac{\epsilon}{2}\\
            & P^{\mathcal{M}_2}(V_1=0|U_1=1) = 1 -\frac{\epsilon}{2}
        \end{align*}
        More over, we have
        \begin{equation*}
            \sum_{U_1=0, \mathbf{U}' \setminus \{ U_1\}} \prod_{j>1}P(v_j|\Pa{V_j}{\mathcal{G}'}) + \sum_{U_1=1, \mathbf{U}' \setminus \{ U_1\}} \prod_{j>1}P(v_j|\Pa{V_j}{\mathcal{G}'}) = Q[\mathbf{V}'\setminus\{V_1\}] = \left(\frac{1}{2}\right)^{n-1}
        \end{equation*}
        This yields
        \begin{align*}
            & 2^{n-1}Q^{\mathcal{M}_1}[\mathbf{V}'](\mathbf{0}) = \left( 1 - \frac{\epsilon}{2} \right)a + \frac{\epsilon}{2} b, \\
            & 2^{n-1}Q^{\mathcal{M}_2}[\mathbf{V}'](\mathbf{0}) = \left( 1 - \frac{\epsilon}{2} \right)b + \frac{\epsilon}{2} a,
        \end{align*}
        where 
        \begin{align*}
            & a = \sum_{U_1=0, \mathbf{U}' \setminus \{ U_1\}} \prod_{j>1}P(V_j=0|\Pa{V_j}{\mathcal{G}'}), \\
            & b = \sum_{U_1=1, \mathbf{U}' \setminus \{ U_1\}} \prod_{j>1}P(V_j=0|\Pa{V_j}{\mathcal{G}'}).
        \end{align*}
        To prove that $Q^{\mathcal{M}_1}[\mathbf{V}'](\mathbf{0}) \neq Q^{\mathcal{M}_2}[\mathbf{V}'](\mathbf{0})$, it is enough to show that $a\neq b$.

        Denote by $S_n$ an observed variable connected to the $V_1$ by a bidirect edge in $\mathcal{G}'_{\mathbf{\mathbf{V}'}}$.
        We define $\mathbf{V}'_{n-1} := \mathbf{V}'\setminus \{V_1\}$, $\mathbf{U}'_{n-1} := \mathbf{U}'\setminus \{U_1\}$ and $\mathcal{G}_{n-1}:=\mathcal{G}'[\mathbf{V}' \setminus \{V_1\}]$.
        We also define models $\mathcal{M}_1^{(n-1)}$ and $\mathcal{M}_2^{(n-1)}$ as follows:

        \textbf{New model $\mathcal{M}_1^{(n-1)}$}: For $V \in \mathbf{V}_{n-1}'$:
        \begin{align}
            V = 
            \begin{cases}
                \bigoplus \Pa{V}{\mathcal{G}_{n-1}}, \quad \text{with probability } 1-\epsilon,\\
                1, \quad \text{with probability } \frac{\epsilon}{2},\\
                0, \quad \text{with probability } \frac{\epsilon}{2},
            \end{cases}
        \end{align}
        and for $U \in \mathbf{U}'_{n-1}$:
        \begin{equation*}
            P(U=0)= P(U=1) = 0.5.
        \end{equation*}

        \textbf{Model $\mathcal{M}_2^{(n-1)}$}:
        For all $V$ in $\mathbf{V}'_{n-1}\setminus \{S_{n}\}$:
        \begin{align}
            V = 
            \begin{cases}
                \bigoplus \Pa{V}{\mathcal{G}_{n-1}}, \quad \text{with probability } 1-\epsilon \\
                1, \quad \text{with probability } \frac{\epsilon}{2},\\
                0, \quad \text{with probability } \frac{\epsilon}{2},
            \end{cases}
        \end{align}
        and for $S_{n}$:
        \begin{align}
            S_n = 
            \begin{cases}
                \urcorner\bigoplus \Pa{S_{n}}{\mathcal{G}_{n-1}}, \quad \text{with probability } 1-\epsilon \\
                1, \quad \text{with probability } \frac{\epsilon}{2},\\
                0, \quad \text{with probability } \frac{\epsilon}{2}.
            \end{cases}
        \end{align}
        Similar to the first model, for each unobserved variables $U\in\mathbf{U}'_{n-1}$, we define
        \begin{equation*}
            P(U=0)= P(U=1) = 0.5.
        \end{equation*}
        Note that:
        \begin{align*}
            & \left( \frac{1}{2} \right)^{n-2}\sum_{U_1=0, \mathbf{U}'_{n-1}} \prod_{j>1}P(V_j|\Pa{V_j}{\mathcal{G}'}) =   \left( \frac{1}{2} \right)^{n-2}a = Q^{\mathcal{M}_1^{(n-1)}}[\mathbf{V}'_{n-1}](\mathbf{0}),\\
            & \left( \frac{1}{2} \right)^{n-2}\sum_{U_1=1, \mathbf{U}'_{n-1}} \prod_{j>1}P(V_j|\Pa{V_j}{\mathcal{G}'}) =   \left( \frac{1}{2} \right)^{n-2}b =   Q^{\mathcal{M}_2^{(n-1)}}[\mathbf{V}'_{n-1}](\mathbf{0}).
        \end{align*}
        It remains to show  $Q^{\mathcal{M}_1^{(n-1)}}[\mathbf{V}'_{n-1}](\mathbf{0})\neq Q^{\mathcal{M}_2^{(n-1)}}[\mathbf{V}'_{n-1}](\mathbf{0})$. 
        Note that if this holds, then by our construction, $Q^{\mathcal{M}_1}[\mathbf{V}'](\mathbf{0})\neq Q^{\mathcal{M}_2}[\mathbf{V}'](\mathbf{0})$.
        In other words, we could reduce the size of the graph while keeping the same problem. Thus, by continuing this procedure, we eventually reach graph $\mathcal{G}_2$ that consists of only two observed nodes and showing $Q^{\mathcal{M}_1^{(2)}}[\mathbf{V}'_{2}](\mathbf{0})\neq Q^{\mathcal{M}_2^{(2)}}[\mathbf{V}'_{2}](\mathbf{0})$ in that graph will conclude the result.
        For graph $\mathcal{G}_2$, we have
        \begin{align*}
            & Q^{\mathcal{M}_1^{(2)}}[\mathbf{V}'_{2}](\mathbf{0}) =\left( \frac{\epsilon}{2}\right)^2 + 2\frac{\epsilon}{2}(1-\epsilon)\frac{1}{2}+(1-\epsilon)^2\frac{1}{2}, \\
            & Q^{\mathcal{M}_2^{(2)}}[\mathbf{V}'_{2}](\mathbf{0}) = \left( \frac{\epsilon}{2}\right)^2 + 2\frac{\epsilon}{2}(1-\epsilon)\frac{1}{2}.
        \end{align*}
        This clearly shows that $Q^{\mathcal{M}_1^{(2)}}[\mathbf{V}'_{2}](\mathbf{0})\neq Q^{\mathcal{M}_2^{(2)}}[\mathbf{V}'_{2}](\mathbf{0})$.
    \end{proof}

